// THE NEON SKYLINE: the user's picture (twin towers, screens, palms; its cut-out sky kept transparent), used as is
// on the right of the NEON AVENUE beyond the monorail rail (src3d/env_canyon.js cnSkyline). 2048x1365 WebP with alpha.
const SKYLINE_ART = { w: 2048, h: 1365, src: 'data:image/webp;base64,' };
if (typeof Image !== "undefined") { SKYLINE_ART.img = new Image(); SKYLINE_ART.img.src = SKYLINE_ART.src; }
